"""Validate saved results, paired schemas and exact continuation/recovery identities."""
import json
from pathlib import Path


def validate(root, arms):
    rows = json.loads((root / 'mechanical-audit.json').read_text(encoding='utf8'))
    assert len(rows) == 24
    target = {'continue', 'gap', 'pinned', 'recovery'}
    for row in rows:
        name = row['name']
        assert row['delivery'] and row['saved_body_matches'], name
        assert row['original_versions_unchanged'] and row['exact_evidence_bindings'], name
        assert row['all_navigation_displays_match_arm'], name
        assert row['semantic_review'] is not None, name
        if row['case'] in target:
            assert row['semantic_review']['full_task_pass'], name
            assert all(row[key] for key in ('marker_initially_hidden', 'marker_in_body', 'marker_in_cited_original')), name
            if row['case'] != 'recovery':
                assert row['performed_live_continuation'], name
                locators = row['first_work_packet']['source_locators']
                for loc in locators:
                    if 'next_offset' not in loc:
                        continue
                    end = 0
                    for start, stop in loc['read_intervals']:
                        if start > end:
                            break
                        end = max(end, stop)
                    assert loc['next_offset'] == end, name
                if row['case'] == 'gap':
                    assert locators[0]['next_offset'] < 10000, name
            if row['case'] == 'pinned':
                assert row['no_new_fetch_after_prefix'], name
                assert all(c['args'].get('revision') == 1 and c['args'].get('id') == 'source-navigation-manual'
                           for c in row['calls'] if c['tool'] == 'knowledge_read'), name
            if row['case'] == 'recovery':
                assert row['performed_receipt_recovery'] and row['no_new_fetch_after_prefix'], name
                allowed = [v['recover']['args']['result_ref'] for v in row['first_work_packet']['omitted_windows']]
                assert allowed, name
                assert all(c['args'].get('result_ref') in allowed for c in row['calls'] if c['tool'] == 'read_tool_result'), name
        if row['case'] == 'short':
            assert row['semantic_review']['full_task_pass'] and len(row['new_claims']) == 1, name
            claim = row['new_claims'][0]
            assert claim['status'] == 'candidate' and claim['content'].rstrip('。') == 'SQLite 从 3.22.0 开始放宽只读 WAL 限制', name
            bindings = {(b['evidence_id'], b['evidence_revision']) for b in row['answer']['provenance']['evidence_bindings']}
            assert claim['references'] and all((ref['target'], ref['revision']) in bindings for ref in claim['references']), name
        match = [r for r in rows if r['case'] == row['case'] and r['seed'] == row['seed'] and r['arm'] != row['arm']]
        assert len(match) == 1 and match[0]['first_tool_schema_sha256'] == row['first_tool_schema_sha256'], name
    summary = {}
    for case in sorted(target | {'long', 'short', 'ALL', 'TARGET'}):
        subset = [r for r in rows if case == 'ALL' or (case == 'TARGET' and r['case'] in target) or r['case'] == case]
        data = {}
        for arm in arms:
            selected = [r for r in subset if r['arm'] == arm]
            data[arm] = {'runs': len(selected), 'deliveries': sum(r['delivery'] for r in selected),
                         'full_task_pass': sum(r['semantic_review']['full_task_pass'] for r in selected),
                         'requests': sum(r['requests'] for r in selected),
                         'input': sum(r['input_tokens'] for r in selected),
                         'output': sum(r['output_tokens'] for r in selected)}
        data['input_change_percent'] = (data[arms[1]]['input'] / data[arms[0]]['input'] - 1) * 100
        summary[case] = data
    assert summary['TARGET']['input_change_percent'] < 0
    (root / 'validated-summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding='utf8')
    return summary


if __name__ == '__main__':
    prod = Path(__file__).resolve().parent
    ab = prod.parent / 'research-navigation-ab-v2-20261103'
    print('AB', json.dumps(validate(ab, ('baseline', 'compact')), ensure_ascii=False, indent=2))
    print('PRODUCTION', json.dumps(validate(prod, ('original_control', 'production')), ensure_ascii=False, indent=2))
